// ─── Types ─────────────────────────────────────────────────────────────────────

import { distributors as egyptDistributors } from './distributors-data'

export type Lang = 'en' | 'ar'

export interface Company {
  id: string
  slug: string
  name: string
  nameAr: string
  tagline: string
  taglineAr: string
  description: string
  descriptionAr: string
  logo: string        // path or URL
  coverImage: string
  services: { title: string; titleAr: string; desc: string; descAr: string }[]
  contact: { email: string; phone: string; address: string; addressAr: string; website?: string }
  externalUrl?: string
}

export type ProductCategory =
  | 'seeds'
  | 'sona-plant-plastic'
  | 'hoses'
  | 'fertilizers-pesticides'
  | 'soil'

export interface Product {
  id: string
  slug: string
  companyId: string
  category: ProductCategory
  name: string
  nameAr: string
  shortDescription: string
  shortDescriptionAr: string
  description: string
  descriptionAr: string
  images: string[]
  targetCrops: string[]
  targetCropsAr: string[]
  targetDiseases: string[]     // disease IDs
  benefits: string[]
  benefitsAr: string[]
  usageInstructions: string
  usageInstructionsAr: string
  applicationMethod: string
  applicationMethodAr: string
  aiRecommended?: boolean
}

export interface Disease {
  id: string
  slug: string
  name: string
  nameAr: string
  scientificName?: string
  description: string
  descriptionAr: string
  cause: string
  causeAr: string
  affectedCrops: string[]
  affectedCropsAr: string[]
  symptoms: string[]
  symptomsAr: string[]
  treatmentSteps: string[]
  treatmentStepsAr: string[]
  preventionTips: string[]
  preventionTipsAr: string[]
  severity: 'low' | 'medium' | 'high'
  image: string
  recommendedProductIds: string[]
}

export interface Distributor {
  id: string
  name: string
  nameAr: string
  region: string
  regionAr: string
  wilaya: string
  wilayaAr: string
  address: string
  addressAr: string
  phone: string
  whatsapp: string
  lat: number
  lng: number
}

